from pathlib import Path
import base64
from PIL import Image

PNG_B64 = ""
root = Path(__file__).resolve().parents[2]
png_path = root / "studio_monitor_icon.png"
ico_path = root / "studio_monitor.ico"
png_path.write_bytes(base64.b64decode(PNG_B64))
img = Image.open(png_path).convert("RGBA")
img.save(ico_path, format="ICO", sizes=[(16,16),(24,24),(32,32),(48,48),(64,64),(128,128),(256,256)])
print(f"generated {png_path.name} and {ico_path.name}")
